# ════════════════════════════════════════════════════════════════
# USUÁRIOS — persistência via GitHub API (fonte primária)
# ════════════════════════════════════════════════════════════════
_USERS_DEFAULT = {
    "ADMIN": {
        "senha_hash": None,  # preenchido abaixo após hash_senha estar definido
        "perfil": "gestor",
        "nome": "Administrador",
        "ultimo_acesso": None
    }
}

def _gh_secrets():
    """Retorna (token, repo, branch) dos secrets do Streamlit."""
    try:
        token  = st.secrets.get("GH_TOKEN","")
        repo   = st.secrets.get("GH_REPO","")
        branch = st.secrets.get("GH_BRANCH","principal")
        return token, repo, branch
    except Exception:
        return "", "", "principal"

def _gh_get_file(api_url, token):
    """GET na API do GitHub. Retorna (conteúdo_bytes, sha) ou (None, '')."""
    import urllib.request
    try:
        req = urllib.request.Request(
            api_url,
            headers={"Authorization": f"token {token}",
                     "Accept": "application/vnd.github.v3+json"}
        )
        with urllib.request.urlopen(req, timeout=10) as r:
            data = json.loads(r.read().decode())
        content = base64.b64decode(data["content"].replace("\n",""))
        return content, data.get("sha","")
    except Exception:
        return None, ""

def _gh_put_file(api_url, token, branch, content_bytes, sha, message="update users.json"):
    """PUT na API do GitHub. Retorna True se ok."""
    import urllib.request
    try:
        payload = json.dumps({
            "message": message,
            "content": base64.b64encode(content_bytes).decode(),
            "sha": sha,
            "branch": branch
        }).encode()
        req = urllib.request.Request(
            api_url, data=payload, method="PUT",
            headers={"Authorization": f"token {token}",
                     "Content-Type": "application/json",
                     "Accept": "application/vnd.github.v3+json"}
        )
        with urllib.request.urlopen(req, timeout=15): pass
        return True
    except Exception:
        return False

def load_users():
    """Carrega usuários: 1º tenta GitHub, 2º arquivo local, 3º default."""
    token, repo, branch = _gh_secrets()

    # 1. Tentar GitHub (fonte primária — persiste entre reboots)
    if token and repo:
        api_url = f"https://api.github.com/repos/{repo}/contents/data/users.json"
        content, _err = _gh_get_file(api_url, token)
        if content:
            try:
                users = json.loads(content.decode("utf-8"))
                # Salva localmente como cache
                os.makedirs(DATA_DIR, exist_ok=True)
                with open(USERS_FILE,"w",encoding="utf-8") as f:
                    f.write(json.dumps(users, ensure_ascii=False, indent=2))
                return users
            except Exception:
                pass

    # 2. Arquivo local (cache ou deploy sem GitHub configurado)
    if os.path.exists(USERS_FILE):
        try:
            with open(USERS_FILE,"r",encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            pass

    # 3. Default mínimo
    return {
        "ADMIN": {
            "senha_hash": hash_senha("admin2025"),
            "perfil": "gestor",
            "nome": "Administrador",
            "ultimo_acesso": None
        }
    }

def save_users(users):
    """Salva usuarios: 1o GitHub (persistente), 2o arquivo local (cache).
    Retorna (gh_ok: bool, erro: str)."""
    os.makedirs(DATA_DIR, exist_ok=True)
    content_str = json.dumps(users, ensure_ascii=False, indent=2)
    content_bytes = content_str.encode("utf-8")
    gh_ok = False
    gh_err = "GitHub nao configurado"
    token, repo, branch = _gh_secrets()
    if token and repo:
        try:
            api_url = f"https://api.github.com/repos/{repo}/contents/data/users.json"
            _, sha_or_err = _gh_get_file(api_url, token)
            sha = sha_or_err if (sha_or_err and not str(sha_or_err).startswith("HTTP")) else ""
            resultado = _gh_put_file(api_url, token, branch, content_bytes, sha)
            # compatível com retorno bool OU tupla (bool, str)
            if isinstance(resultado, tuple):
                gh_ok, gh_err = resultado
            else:
                gh_ok = bool(resultado)
                gh_err = "" if gh_ok else "Falha no envio"
        except Exception as e:
            gh_ok = False
            gh_err = str(e)
    try:
        with open(USERS_FILE, "w", encoding="utf-8") as f:
            f.write(content_str)
    except Exception:
        pass
    return gh_ok, gh_err

def registrar_acesso(login):
    users = st.session_state.get("users_db", load_users())
    if login in users:
        try:
            agora_brt = datetime.datetime.utcnow() - datetime.timedelta(hours=3)
            users[login]["ultimo_acesso"] = agora_brt.strftime("%Y-%m-%dT%H:%M:%S")
            save_users(users)
            st.session_state.users_db = users
        except Exception:
            pass  # nunca travar o login por causa de persistência

# ════════════════════════════════════════════════════════════════
# CARREGAMENTO DE DADOS
# ════════════════════════════════════════════════════════════════
@st.cache_data(show_spinner=False)
def load_area(src):
    if isinstance(src, BytesIO): src.seek(0)
    raw = pd.read_excel(src, header=None)

    # Detectar linha de header — procura linha com "VENDEDOR" ou "CONSULTOR" ou "REGIÃO"
    header_row = 0
    for i in range(min(5, len(raw))):
        vals = raw.iloc[i].astype(str).str.upper().tolist()
        if any(k in v for v in vals for k in ["VENDED","CONSUL","REGI","MUNIC"]):
            header_row = i
            break

    if isinstance(src, BytesIO): src.seek(0)
    df = pd.read_excel(src, header=header_row)
    df.columns = [str(c).strip() for c in df.columns]

    # Mapear colunas pelo nome
    col_map = {}
    for c in df.columns:
        cu = str(c).upper()
        if any(k in cu for k in ["VENDED","CONSUL"]): col_map[c] = "Consultor"
        elif "REGI" in cu:    col_map[c] = "Regiao"
        elif "MUNIC" in cu:   col_map[c] = "Municipio"
        elif "BAIRRO" in cu:  col_map[c] = "Bairro"
        elif "CEP" in cu and ("INIC" in cu or "INÍC" in cu): col_map[c] = "CEP_Inicial"
        elif "CEP" in cu and ("FIN" in cu or "FINA" in cu):  col_map[c] = "CEP_Final"
    df = df.rename(columns=col_map)

    # Garantir todas as colunas necessárias
    for col in ["Regiao","Municipio","Bairro","Consultor","CEP_Inicial","CEP_Final"]:
        if col not in df.columns: df[col] = ""

    # Limpar e normalizar
    df = df[df["Consultor"].astype(str).str.strip().str.upper() != "NAN"].copy()
    df = df[df["Consultor"].astype(str).str.strip() != ""].copy()
    df["Consultor"]      = norm_str_series(df["Consultor"].fillna("ZONA LIVRE"))
    df["Municipio_norm"] = norm_str_series(df["Municipio"])
    df["Bairro_norm"]    = norm_str_series(df["Bairro"].fillna(""))
    df["CEP_ini_norm"]   = df["CEP_Inicial"].astype(str).str.replace(r"\D","",regex=True).str.zfill(8).str[:8]
    df["CEP_fim_norm"]   = df["CEP_Final"].astype(str).str.replace(r"\D","",regex=True).str.zfill(8).str[:8]

    # ── Cidade_real: cidade que aparece em NO_CIDADE dos emplacamentos ──
    # Para SP Capital os municípios são bairros — cidade real é "SAO PAULO"
    # Para Grande SP os municípios já são cidades reais
    def _cidade_real(row):
        regiao = norm_str(str(row.get("Regiao", "")))
        if "SAO PAULO CAPITAL" in regiao or "CAPITAL" in regiao:
            return "SAO PAULO"
        # Grande SP ou outros — usar o Município como cidade real
        return norm_str(str(row.get("Municipio", "")))

    df["Cidade_real"] = df.apply(_cidade_real, axis=1)

    return df.reset_index(drop=True)

@st.cache_data(show_spinner=False)
def load_carteira(src):
    if isinstance(src, BytesIO): src.seek(0)
    df = pd.read_excel(src)
    df.columns = [c.strip() for c in df.columns]
    df["CPF/CNPJ"]  = df["CPF/CNPJ"].astype(str).str.strip()
    df["CNPJ_NORM"] = df["CPF/CNPJ"].astype(str).str.replace(r"\D","",regex=True)
    df["VENDEDOR"]  = df.get("VENDEDOR", pd.Series(dtype=str)).astype(str).str.strip()
    if "CEP" in df.columns:
        df["CEP_norm"] = df["CEP"].apply(norm_cep)
    return df

@st.cache_data(show_spinner=False)
def load_emplacamentos(src, label=""):
    if isinstance(src, BytesIO): src.seek(0)
    # Detectar linha do header (procura "Chassi" nas primeiras 15 linhas; default=0)
    raw = pd.read_excel(src, header=None, nrows=15)
    header_row = 0
    for i in range(len(raw)):
        if any("Chassi" in str(v) for v in raw.iloc[i].tolist()):
            header_row = i; break
    if isinstance(src, BytesIO): src.seek(0)
    df = pd.read_excel(src, header=header_row)
    df.columns = [str(c).strip() for c in df.columns]

    # Normalizar campos de texto essenciais
    for col in ["CPFCNPJPROPRIETARIO","NOMEPROPRIETARIO","NO_CIDADE","NO_BAIRRO",
                "Placa","Chassi","Concessionário","Modelo","Marca","Segmento"]:
        if col in df.columns:
            df[col] = df[col].astype(str).str.strip()

    # CNPJ normalizado (só dígitos) — vetorizado
    df["CNPJ_NORM"] = df["CPFCNPJPROPRIETARIO"].astype(str).str.replace(r"\D", "", regex=True)

    # Data — tenta dayfirst (dd/mm/yyyy) e mixed
    df["Data emplacamento"] = pd.to_datetime(
        df["Data emplacamento"], dayfirst=True, errors="coerce"
    )
    # Fallback para formato americano se muitos nulos
    if df["Data emplacamento"].isna().sum() > len(df) * 0.5:
        df["Data emplacamento"] = pd.to_datetime(
            df["Data emplacamento"], errors="coerce"
        )

    df["Ano"] = df["Data emplacamento"].dt.year
    df["Mes"] = df["Data emplacamento"].dt.month

    df["Placa_norm"] = df["Placa"].str.replace("-","").str.replace(" ","").str.upper()
    df["NO_CIDADE_NORM"] = norm_str_series(df["NO_CIDADE"])
    df["NO_BAIRRO_NORM"] = norm_str_series(df["NO_BAIRRO"].fillna(""))

    if "NU_CEP" in df.columns:
        # CEP: float(6529220.0) → int(6529220) → zfill → "06529220"
        # Não usar str.replace direto pois float perde o zero inicial
        df["CEP_norm"] = df["NU_CEP"].apply(norm_cep)
    else:
        df["CEP_norm"] = ""

    # Remover linhas sem data válida
    df.dropna(subset=["Ano"], inplace=True)
    df["Ano"] = df["Ano"].astype(int)
    df["Mes"] = df["Mes"].astype(int)
    df["_fonte"] = label
    return df

def merge_emp(dfs):
    m = pd.concat(dfs, ignore_index=True)
    m.drop_duplicates(subset=["Chassi"], keep="last", inplace=True)
    m.sort_values("Data emplacamento", inplace=True)
    return m

def get_consultor(cep_norm, cidade_norm, bairro_norm, df_area):
    """Retorna consultor por CEP (faixa) — critério principal.
    Fallback por Cidade_real quando não há CEP válido.
    """
    if df_area is None: return None
    # 1. CEP (sempre preferido)
    if cep_norm and len(cep_norm) == 8:
        matches = df_area[
            (df_area["CEP_ini_norm"] != "") &
            (df_area["CEP_ini_norm"] <= cep_norm) &
            (df_area["CEP_fim_norm"] >= cep_norm)
        ]
        if not matches.empty:
            return matches.iloc[0]["Consultor"]
    # 2. Cidade real (fallback — usa Cidade_real mapeada se disponível)
    col_cidade = "Cidade_real" if "Cidade_real" in df_area.columns else "Municipio_norm"
    m = df_area[df_area[col_cidade] == cidade_norm]
    if not m.empty: return m.iloc[0]["Consultor"]
    return None

def get_munic_area(consultor, df_area):
    """Retorna (cidades_reais, cep_ranges) para o consultor.
    Usa Cidade_real (bairros de SP Capital mapeados para 'SAO PAULO').
    """
    if df_area is None: return [], []
    sub = df_area[df_area["Consultor"] == consultor]
    col_cidade = "Cidade_real" if "Cidade_real" in df_area.columns else "Municipio_norm"
    cidades = sub[col_cidade].dropna().unique().tolist()
    cidades = [c for c in cidades if c]
    cep_ranges = sub[sub["CEP_ini_norm"] != ""][["CEP_ini_norm","CEP_fim_norm"]].values.tolist()
    return cidades, cep_ranges

def emp_da_area(df_emp, cidades_reais, cep_ranges):
    """Filtra emplacamentos da área.
    Regra: CEP é o critério principal (sempre preferido).
    Fallback por cidade real (ex: 'SAO PAULO', 'GUARULHOS') para registros sem CEP válido.
    cidades_reais já foi mapeado pelo load_area (bairros SP → 'SAO PAULO').
    """
    if df_emp is None or df_emp.empty: return pd.DataFrame()

    # ── 1. Filtro por CEP (faixas da área operacional) ──
    mask_cep = pd.Series(False, index=df_emp.index)
    if cep_ranges:
        for ini, fim in cep_ranges:
            if ini and fim:
                mask_cep |= (
                    (df_emp["CEP_norm"].str.len() == 8) &
                    (df_emp["CEP_norm"] >= ini) &
                    (df_emp["CEP_norm"] <= fim)
                )

    # ── 2. Filtro por cidade real (fallback para registros sem CEP válido) ──
    cidade_set = set(c for c in cidades_reais if c)
    sem_cep = df_emp["CEP_norm"].str.len() != 8
    mask_cidade = df_emp["NO_CIDADE_NORM"].isin(cidade_set) & sem_cep

    mask_final = mask_cep | mask_cidade
    return df_emp[mask_final].copy()

def gerar_relatorio_emplacamento(emp_mes, emp_area, cnpjs_carteira_set, todos_cnpjs_cart,
                                  sel_mes_lbl, sel_ano, consultor_nome):
    """Gera relatório XLSX estilizado igual ao modelo — cabeçalho colorido + tabela de dados."""
    from openpyxl import Workbook
    from openpyxl.styles import (Font, PatternFill, Alignment, Border, Side,
                                  GradientFill)
    from openpyxl.utils import get_column_letter

    wb = Workbook()
    ws = wb.active
    ws.title = f"{sel_mes_lbl[:3]} {sel_ano}"

    # ── Paletas ──
    PRETO    = "FF1A1A1A"
    BRANCO   = "FFFFFFFF"
    VERDE    = "FF1E7E34"
    VERDE_CL = "FF28A745"
    VERMELHO = "FFC0392B"
    AZUL     = "FF1A3F6F"
    CINZA_CL = "FFF2F2F2"
    AMARELO  = "FFFFF2CC"
    ROSA_CL  = "FFFCE8E8"
    AZUL_CL  = "FFE8F0FF"

    thin = Side(style="thin", color="FFCCCCCC")
    borda_fina = Border(left=thin, right=thin, top=thin, bottom=thin)

    def fill(hex_color):
        return PatternFill("solid", start_color=hex_color, end_color=hex_color)

    def font(bold=False, color=BRANCO, size=11, italic=False):
        return Font(name="Arial", bold=bold, color=color, size=size, italic=italic)

    def aln(h="center", v="center", wrap=False):
        return Alignment(horizontal=h, vertical=v, wrap_text=wrap)

    # ── Colunas ──
    ws.column_dimensions["A"].width = 14   # Data
    ws.column_dimensions["B"].width = 22   # CNPJ
    ws.column_dimensions["C"].width = 40   # Cliente
    ws.column_dimensions["D"].width = 28   # Modelo
    ws.column_dimensions["E"].width = 22   # Chassi
    ws.column_dimensions["F"].width = 25   # Concessionária
    ws.column_dimensions["G"].width = 18   # Cidade

    # ════════════════════════════════════
    # LINHA 1 — Título principal
    # ════════════════════════════════════
    ws.merge_cells("A1:G1")
    ws.row_dimensions[1].height = 36
    c = ws["A1"]
    periodo = f"{sel_mes_lbl.upper()} DE {sel_ano}"
    c.value = f"EMPLACAMENTO ACUMULADO — {periodo}"
    c.font = Font(name="Arial", bold=True, color=BRANCO, size=14)
    c.fill = fill(PRETO)
    c.alignment = aln("center")

    # Consultor
    ws.merge_cells("A2:G2")
    ws.row_dimensions[2].height = 18
    c = ws["A2"]
    c.value = f"Consultor: {consultor_nome.title()}"
    c.font = Font(name="Arial", bold=False, color="FFAAAAAA", size=10, italic=True)
    c.fill = fill(PRETO)
    c.alignment = aln("center")

    # ════════════════════════════════════
    # LINHAS 3-4 — Cabeçalhos dos grupos
    # ════════════════════════════════════
    ws.row_dimensions[3].height = 30
    ws.row_dimensions[4].height = 26

    # Calcular grupos
    g1 = emp_mes[~emp_mes["CNPJ_NORM"].isin(todos_cnpjs_cart)]
    g2 = emp_mes[emp_mes["CNPJ_NORM"].isin(cnpjs_carteira_set) & ~is_denigris(emp_mes["Concessionário"])]
    g3 = emp_mes[is_denigris(emp_mes["Concessionário"])]
    total = len(emp_mes)

    def pct(n): return f"{round(n/total*100) if total else 0}%"

    # Col A: total emplacamentos (verde)
    ws["A3"].value = "EMPLACAMENTOS"
    ws["A3"].font = font(bold=True, color=BRANCO, size=10)
    ws["A3"].fill = fill(VERDE_CL)
    ws["A3"].alignment = aln()
    ws["A3"].border = borda_fina

    ws["A4"].value = total
    ws["A4"].font = font(bold=True, color=BRANCO, size=13)
    ws["A4"].fill = fill(VERDE_CL)
    ws["A4"].alignment = aln()
    ws["A4"].border = borda_fina

    # Linha com "100%"
    ws.row_dimensions[5].height = 20
    ws["A5"].value = "100%"
    ws["A5"].font = font(bold=True, color=BRANCO, size=11)
    ws["A5"].fill = fill(VERDE_CL)
    ws["A5"].alignment = aln()
    ws["A5"].border = borda_fina

    # Cols B-C: Não na carteira (preto)
    ws.merge_cells("B3:C3")
    ws.merge_cells("B4:C4")
    ws.merge_cells("B5:C5")
    ws["B3"].value = "EMPLACAMENTO DE VEÍCULOS QUE NÃO ESTÃO NA CARTEIRA"
    ws["B3"].font = font(bold=True, color=BRANCO, size=9)
    ws["B3"].fill = fill(PRETO)
    ws["B3"].alignment = aln("center", wrap=True)
    ws["B3"].border = borda_fina
    ws["B4"].value = len(g1)
    ws["B4"].font = font(bold=True, color=BRANCO, size=13)
    ws["B4"].fill = fill(PRETO)
    ws["B4"].alignment = aln()
    ws["B4"].border = borda_fina
    ws["B5"].value = pct(len(g1))
    ws["B5"].font = font(bold=True, color=BRANCO, size=11)
    ws["B5"].fill = fill(PRETO)
    ws["B5"].alignment = aln()
    ws["B5"].border = borda_fina

    # Cols D-E: Carteira + concorrência (vermelho)
    ws.merge_cells("D3:E3")
    ws.merge_cells("D4:E4")
    ws.merge_cells("D5:E5")
    ws["D3"].value = "EMPLACAMENTO DE VEÍCULOS QUE ESTÃO NA CARTEIRA E COMPROU NA CONCORRÊNCIA"
    ws["D3"].font = font(bold=True, color=BRANCO, size=9)
    ws["D3"].fill = fill(VERMELHO)
    ws["D3"].alignment = aln("center", wrap=True)
    ws["D3"].border = borda_fina
    ws["D4"].value = len(g2)
    ws["D4"].font = font(bold=True, color=BRANCO, size=13)
    ws["D4"].fill = fill(VERMELHO)
    ws["D4"].alignment = aln()
    ws["D4"].border = borda_fina
    ws["D5"].value = pct(len(g2))
    ws["D5"].font = font(bold=True, color=BRANCO, size=11)
    ws["D5"].fill = fill(VERMELHO)
    ws["D5"].alignment = aln()
    ws["D5"].border = borda_fina

    # Cols F-G: De Nigris (azul)
    ws.merge_cells("F3:G3")
    ws.merge_cells("F4:G4")
    ws.merge_cells("F5:G5")
    ws["F3"].value = "EMPLACAMENTO DE VEÍCULOS QUE COMPROU NA DE NIGRIS"
    ws["F3"].font = font(bold=True, color=BRANCO, size=9)
    ws["F3"].fill = fill(AZUL)
    ws["F3"].alignment = aln("center", wrap=True)
    ws["F3"].border = borda_fina
    ws["F4"].value = len(g3)
    ws["F4"].font = font(bold=True, color=BRANCO, size=13)
    ws["F4"].fill = fill(AZUL)
    ws["F4"].alignment = aln()
    ws["F4"].border = borda_fina
    ws["F5"].value = pct(len(g3))
    ws["F5"].font = font(bold=True, color=BRANCO, size=11)
    ws["F5"].fill = fill(AZUL)
    ws["F5"].alignment = aln()
    ws["F5"].border = borda_fina

    # ════════════════════════════════════
    # LINHA 6 — Total clientes + % De Nigris
    # ════════════════════════════════════
    ws.row_dimensions[6].height = 22
    ws.merge_cells("A6:C6")
    ws["A6"].value = f"TOTAL DE CLIENTES ÚNICOS: {emp_mes['CNPJ_NORM'].nunique()}"
    ws["A6"].font = font(bold=True, color="FF1A1A1A", size=10)
    ws["A6"].fill = fill("FFE0E0E0")
    ws["A6"].alignment = aln("left")
    ws["A6"].border = borda_fina

    nigris_uniq = g3["CNPJ_NORM"].nunique()
    tot_uniq    = emp_mes["CNPJ_NORM"].nunique()
    ws.merge_cells("D6:E6")
    ws["D6"].value = f"De Nigris: {nigris_uniq} clientes ({round(nigris_uniq/tot_uniq*100) if tot_uniq else 0}%)"
    ws["D6"].font = font(bold=True, color=BRANCO, size=10)
    ws["D6"].fill = fill(AZUL)
    ws["D6"].alignment = aln("center")
    ws["D6"].border = borda_fina

    ws.merge_cells("F6:G6")
    ws["F6"].value = ""
    ws["F6"].fill = fill("FFE0E0E0")
    ws["F6"].border = borda_fina

    # ════════════════════════════════════
    # LINHA 7 — TOP 3 CLIENTES (histórico da área)
    # ════════════════════════════════════
    ws.row_dimensions[7].height = 20
    ws.merge_cells("A7:G7")
    ws["A7"].value = "🏆  TOP 3 CLIENTES — HISTÓRICO DA ÁREA"
    ws["A7"].font = Font(name="Arial", bold=True, color=BRANCO, size=10)
    ws["A7"].fill = fill("FF2C3E50")
    ws["A7"].alignment = aln("left")
    ws["A7"].border = borda_fina

    top3 = emp_mes.groupby(["CNPJ_NORM","NOMEPROPRIETARIO","NO_CIDADE"]).agg(
        Total=("Chassi","count"),
        Nigris=("Concessionário", lambda x: is_denigris(x).sum())
    ).reset_index().sort_values("Total", ascending=False).head(3).reset_index(drop=True)

    medals = ["🥇", "🥈", "🥉"]
    for ti, trow in top3.iterrows():
        r = 8 + ti
        ws.row_dimensions[r].height = 20
        pct_n = round(trow["Nigris"]/trow["Total"]*100) if trow["Total"] > 0 else 0
        ws.merge_cells(f"A{r}:B{r}")
        ws[f"A{r}"].value = f"{medals[ti]}  {str(trow['NOMEPROPRIETARIO'])[:38]}"
        ws[f"A{r}"].font = Font(name="Arial", bold=True, color="FF1A1A1A", size=10)
        ws[f"A{r}"].fill = fill(CINZA_CL if ti % 2 == 0 else BRANCO)
        ws[f"A{r}"].alignment = aln("left")
        ws[f"A{r}"].border = borda_fina

        ws.merge_cells(f"C{r}:D{r}")
        ws[f"C{r}"].value = f"📍 {safe_str(trow['NO_CIDADE'])}"
        ws[f"C{r}"].font = Font(name="Arial", size=10, color="FF555555")
        ws[f"C{r}"].fill = fill(CINZA_CL if ti % 2 == 0 else BRANCO)
        ws[f"C{r}"].alignment = aln("left")
        ws[f"C{r}"].border = borda_fina

        ws.merge_cells(f"E{r}:F{r}")
        ws[f"E{r}"].value = f"{int(trow['Total'])} caminhões — {pct_n}% De Nigris"
        cor_t = "FF1E7E34" if pct_n >= 50 else "FFC0392B"
        ws[f"E{r}"].font = Font(name="Arial", bold=True, size=10, color=cor_t)
        ws[f"E{r}"].fill = fill(CINZA_CL if ti % 2 == 0 else BRANCO)
        ws[f"E{r}"].alignment = aln("center")
        ws[f"E{r}"].border = borda_fina

        ws[f"G{r}"].fill = fill(CINZA_CL if ti % 2 == 0 else BRANCO)
        ws[f"G{r}"].border = borda_fina

    # ════════════════════════════════════
    # LINHA 11+ — Cabeçalho da tabela de dados
    # ════════════════════════════════════
    header_row = 11
    ws.row_dimensions[header_row].height = 24
    headers = ["DATA EMPLAC.", "CNPJ", "CLIENTE", "MODELO", "CHASSI", "CONCESSIONÁRIA", "CIDADE"]
    for ci, h in enumerate(headers, 1):
        cell = ws.cell(row=header_row, column=ci)
        cell.value = h
        cell.font = font(bold=True, color=BRANCO, size=10)
        cell.fill = fill("FF1A1A1A")
        cell.alignment = aln("center")
        cell.border = borda_fina

    # ════════════════════════════════════
    # DADOS — todos os emplacamentos do mês
    # ════════════════════════════════════
    emp_sorted = emp_mes.sort_values("Data emplacamento").reset_index(drop=True)

    for di, drow in emp_sorted.iterrows():
        r = header_row + 1 + di
        ws.row_dimensions[r].height = 18

        cnpj_n = str(drow.get("CNPJ_NORM",""))
        is_cart = cnpj_n in cnpjs_carteira_set
        is_dn   = is_denigris(pd.Series([drow.get("Concessionário","")])).iloc[0]
        is_conc = is_cart and not is_dn

        # Cor da linha
        if is_dn:
            row_fill = fill(AZUL_CL)
        elif is_conc:
            row_fill = fill(ROSA_CL)
        else:
            row_fill = fill(BRANCO if di % 2 == 0 else CINZA_CL)

        data_val = drow.get("Data emplacamento")
        if hasattr(data_val, "strftime"):
            data_str = data_val.strftime("%d/%m/%Y")
        else:
            data_str = str(data_val)[:10] if data_val else "—"

        row_data = [
            data_str,
            str(drow.get("CPFCNPJPROPRIETARIO",""))[:20],
            str(drow.get("NOMEPROPRIETARIO",""))[:45],
            str(drow.get("Modelo",""))[:30],
            str(drow.get("Chassi",""))[:20],
            str(drow.get("Concessionário",""))[:35],
            str(drow.get("NO_CIDADE",""))[:20],
        ]
        for ci, val in enumerate(row_data, 1):
            cell = ws.cell(row=r, column=ci, value=val)
            cell.font = Font(name="Arial", size=9, color="FF1A1A1A")
            cell.fill = row_fill
            cell.alignment = Alignment(horizontal="left" if ci > 1 else "center", vertical="center")
            cell.border = borda_fina

    # ════════════════════════════════════
    # LEGENDA
    # ════════════════════════════════════
    leg_row = header_row + len(emp_sorted) + 3
    ws.row_dimensions[leg_row].height = 16
    ws.merge_cells(f"A{leg_row}:G{leg_row}")
    ws[f"A{leg_row}"].value = "LEGENDA:"
    ws[f"A{leg_row}"].font = Font(name="Arial", bold=True, size=9, color="FF1A1A1A")

    for lci, (texto, cor) in enumerate([
        ("  ■  Comprou na De Nigris", AZUL_CL),
        ("  ■  Carteira → Concorrência", ROSA_CL),
        ("  ■  Sem carteira / Neutro", CINZA_CL),
    ]):
        lr = leg_row + 1 + lci
        ws.row_dimensions[lr].height = 14
        ws.merge_cells(f"A{lr}:C{lr}")
        cell = ws[f"A{lr}"]
        cell.value = texto
        cell.font = Font(name="Arial", size=9, color="FF1A1A1A")
        cell.fill = fill(cor)
        cell.border = borda_fina

    buf = BytesIO()
    wb.save(buf)
    buf.seek(0)
    return buf

