# CONTEÚDO
# ════════════════════════════════════════════════════════════════
st.markdown('<div class="page-wrap">', unsafe_allow_html=True)

# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
# PÁGINA: BUSCA DE CLIENTE
# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
if pagina == "busca":
    st.markdown("""<div class="page-header"><h1>🔍 Busca de Cliente</h1>
    <p>Pesquise por razão social, CNPJ ou placa</p></div>""", unsafe_allow_html=True)

    if df_emp is None:
        st.warning("⚠️ Carregue os dados na aba Admin → Gerenciar Dados")
        st.stop()

    q = st.text_input("", placeholder="Nome, CNPJ, CPF ou Placa...", label_visibility="collapsed",
                     value=st.session_state.get("busca_q",""))
    buscar = st.button("Buscar Cliente", use_container_width=True)

    # Persistir q no session_state para não perder ao clicar em botões internos
    if buscar and q:
        st.session_state["busca_q"] = q
        st.session_state["busca_cnpj_sel"] = None  # reset
        st.session_state["busca_linha_placa"] = None

    # Usar q do session_state se não está buscando agora
    if not q:
        q = st.session_state.get("busca_q","")

    _mostrar_resultado = False

    # ── Restaurar busca anterior (quando clica em botão interno como Receita Federal) ──
    if not buscar and st.session_state.get("busca_cnpj_sel"):
        cnpj_sel    = st.session_state["busca_cnpj_sel"]
        linha_placa = st.session_state.get("busca_linha_placa")
        edf  = df_emp[df_emp["CNPJ_NORM"] == cnpj_sel].copy()
        esrt = edf.sort_values("Data emplacamento", ascending=False)
        last = linha_placa if linha_placa else (esrt.iloc[0].to_dict() if not edf.empty else {})
        total_emp   = len(edf)
        datas       = edf["Data emplacamento"].dropna().tolist()
        pred_label, pred_date = calc_prediction(datas)
        nigris_cnt  = int(is_denigris(edf["Concessionário"]).sum())
        cart_row    = None
        if df_cart is not None:
            cr = df_cart[df_cart["CNPJ_NORM"] == cnpj_sel]
            cart_row = cr.iloc[0].to_dict() if not cr.empty else None
        cep_c    = norm_cep(last.get("NU_CEP",""))
        cidade_c = norm_str(str(last.get("NO_CIDADE","")))
        bairro_c = norm_str(str(last.get("NO_BAIRRO","")))
        cons_resp = get_consultor(cep_c, cidade_c, bairro_c, df_area) if df_area is not None else "—"
        _mostrar_resultado = True

    if buscar and q:
        q_strip = q.strip()
        q_norm  = norm_str(q_strip)
        q_cnpj  = re.sub(r"\D", "", q_strip)
        q_placa = q_strip.replace("-","").replace(" ","").upper()

        # ── Detectar busca por placa: sem espaço, só alfanumérico, 5-8 chars ──
        _is_placa = (len(q_placa) >= 5 and len(q_placa) <= 8 and
                     q_placa.isalnum() and " " not in q_placa)

        linha_placa = None

        if _is_placa:
            match_placa = df_emp[df_emp["Placa_norm"] == q_placa]
            if match_placa.empty:
                match_placa = df_emp[df_emp["Placa_norm"].str.contains(q_placa, na=False, regex=False)]
            if not match_placa.empty:
                linha_placa = match_placa.sort_values("Data emplacamento", ascending=False).iloc[0].to_dict()
                cnpj_sel = linha_placa["CNPJ_NORM"]
                edf = df_emp[df_emp["CNPJ_NORM"] == cnpj_sel].copy()
                esrt = edf.sort_values("Data emplacamento", ascending=False)
                last = linha_placa
                total_emp = len(edf)
                datas = edf["Data emplacamento"].dropna().tolist()
                pred_label, pred_date = calc_prediction(datas)
                nigris_cnt = int(is_denigris(edf["Concessionário"]).sum())
            else:
                # Não achou por placa — tenta por nome
                _is_placa = False
        
        if not _is_placa:
            # Busca por nome ou CNPJ
            tokens = [t for t in q_norm.split() if len(t) >= 2]
            nome_norm_series = norm_str_series(df_emp["NOMEPROPRIETARIO"])
            if tokens:
                mask_nome = pd.Series(True, index=df_emp.index)
                for tok in tokens:
                    mask_nome = mask_nome & nome_norm_series.str.contains(tok, na=False, regex=False)
            else:
                mask_nome = pd.Series(False, index=df_emp.index)

            if len(q_cnpj) >= 11:
                mask_cnpj = df_emp["CNPJ_NORM"] == q_cnpj
            elif len(q_cnpj) >= 3:
                mask_cnpj = df_emp["CNPJ_NORM"].str.startswith(q_cnpj)
            else:
                mask_cnpj = pd.Series(False, index=df_emp.index)

            resultados = df_emp[mask_nome | mask_cnpj].copy()
            if not resultados.empty and tokens:
                _nome_s = norm_str_series(resultados["NOMEPROPRIETARIO"])
                resultados["_score"] = sum(_nome_s.str.contains(tok, na=False, regex=False).astype(int) for tok in tokens)
                resultados = resultados.sort_values("_score", ascending=False)

            cnpjs = resultados["CNPJ_NORM"].unique()
            if len(cnpjs) == 0:
                st.warning("Nenhum cliente encontrado.")

            if len(cnpjs) > 1:
                opts = []
                for cn in cnpjs[:20]:
                    sub = df_emp[df_emp["CNPJ_NORM"] == cn]
                    nome = sub["NOMEPROPRIETARIO"].iloc[0]
                    cidade = sub["NO_CIDADE"].iloc[0]
                    total_cn = len(sub)
                    opts.append(f"{nome} — {cidade} ({total_cn} empl.)")
                sel = st.selectbox("Selecione o cliente:", opts)
                cnpj_sel = cnpjs[opts.index(sel)]
            else:
                cnpj_sel = cnpjs[0]

            st.session_state["busca_cnpj_sel"] = cnpj_sel
            st.session_state["busca_linha_placa"] = None
            edf = df_emp[df_emp["CNPJ_NORM"] == cnpj_sel].copy()
            esrt = edf.sort_values("Data emplacamento", ascending=False)
            last = esrt.iloc[0].to_dict()
            total_emp = len(edf)
            datas = edf["Data emplacamento"].dropna().tolist()
            pred_label, pred_date = calc_prediction(datas)
            nigris_cnt = int(is_denigris(edf["Concessionário"]).sum())
            _mostrar_resultado = True

    if _mostrar_resultado:
        # Dados da carteira
        cart_row = None
        if df_cart is not None:
            cr = df_cart[df_cart["CNPJ_NORM"] == cnpj_sel]
            cart_row = cr.iloc[0].to_dict() if not cr.empty else None

        # Consultor responsável
        cep_c  = norm_cep(last.get("NU_CEP",""))
        cid_c  = norm_str(str(last.get("NO_CIDADE","")))
        bai_c  = norm_str(str(last.get("NO_BAIRRO","")))
        consultor_resp = get_consultor(cep_c, cid_c, bai_c, df_area)
        if consultor_resp is None and cart_row:
            consultor_resp = safe_str(cart_row.get("VENDEDOR",""))

        # ── HERO ──
        nome_exib = safe_str(last.get("NOME_FANTASIA","")) if safe_str(last.get("NOME_FANTASIA","")) != "—" else safe_str(last.get("NOMEPROPRIETARIO",""))
        cls_raw = safe_str(cart_row.get("Classificação Mercedes","")) if cart_row else "—"
        badge_h = f'<span class="badge {badge_class(cls_raw)}">{cls_raw}</span>' if cls_raw != "—" else ""
        resp_h = ""
        if cart_row:
            v = safe_str(cart_row.get("VENDEDOR",""))
